test('permits inclusive Count bounds', () => {
  assert.equal(permit(0), true);
  assert.equal(permit(3), true);
});

test('rejects values outside Count bounds and malformed inputs without coercion', () => {
  for (const value of [-1, 4, '3', null, NaN, 1.5]) {
    assert.equal(permit(value), false, `${String(value)} should be rejected`);
  }
});

